"""General custody safeguards, arts 282–300-A, including current court readings."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
JURY='https://portal.stf.jus.br/jurisprudenciarepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5776893&numeroProcesso=1235340&numeroTema=1068'
CUFF='https://noticias.stf.jus.br/postsnoticias/11a-sumula-vinculante-do-stf-limita-o-uso-de-algemas-a-casos-excepcionais/'
DIP='https://portal.stf.jus.br/constituicao-supremo/artigo.asp?abrirArtigo=5&abrirBase=CF'
DNA='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(282,'Cautelares dependem de necessidade, adequação e decisão individualizada; prisão preventiva é última alternativa quando medidas menos gravosas não bastam.', ['Aplicação isolada ou cumulativa.', 'Decretação mediante provocação legal; não usar redação anterior que admitia iniciativa judicial geral.', 'Contraditório prévio: cinco dias, salvo urgência ou risco de ineficácia concretamente fundamentados.', 'Descumprimento: requerimento do MP, assistente ou querelante; substituir, cumular ou, por último, preventiva com requisitos.', 'Revogação ou substituição por falta de motivo pode ocorrer de ofício; nova decretação precisa observar provocação e requisitos atuais.', 'Justificar individualmente por que art. 319 é insuficiente.'], 'Descumprimento não torna prisão automática. Não ler §5º como autorização para restabelecer prisão de ofício sem provocação no modelo atual.', 'Comparecimento periódico é suficiente para risco concreto e afasta prisão mais gravosa.', 'Quebra da medida exige pedido, análise do risco e alternativas, não preventiva mecânica.', ['Preventiva deve examinar alternativas? Sim.', 'Prazo ordinário de contraditório é cinco dias? Sim.'], 'Necessidade cautelar','Risco concreto e medida proporcional, não antecipação de pena.')
add(283,'Prisão segue flagrante ou ordem judicial fundamentada, por cautelar ou condenação definitiva; execução do júri possui entendimento específico do STF.', ['Título e competência precisam ser legítimos.', 'Cautelares do título não se aplicam quando não há pena privativa de liberdade cominada nas formas previstas.', 'Prisão pode ser executada em qualquer dia e hora, respeitado domicílio.', 'Tema 1068/STF: execução imediata da condenação pelo júri independe do total da pena; não generalizar a qualquer condenação.'], 'Não afirmar que toda condenação de segunda instância autoriza execução automática, nem ignorar regra específica do júri.', 'Cautelar judicial fundamentada é cumprida respeitando proteção domiciliar.', 'Condenação pelo júri exige leitura do Tema 1068, sem transportar esse regime para sentença comum.', ['Qualquer hora elimina inviolabilidade da casa? Não.', 'Tema 1068 depende de pena mínima de quinze anos? Não.'], 'Título legítimo da prisão','Fundamento legal e constitucional da privação de liberdade.',[CF,JURY])
add(284,'Força só é admitida na medida indispensável diante de resistência ou tentativa de fuga.', ['Necessidade limita intensidade.', 'Não confundir execução da prisão com punição física.'], 'Prisão lícita não torna toda violência lícita.', 'Resistência concreta é vencida com força estritamente necessária.', 'Preso cooperativo não pode receber agressão por castigo.', ['Força pode ser usada como punição? Não.', 'Resistência autoriza força ilimitada? Não.'], 'Força indispensável','Intervenção necessária para execução legítima.')
add(285,'Autoridade que determina prisão expede mandado com identificação, motivo e demais requisitos.', ['Escrivão lavra; autoridade assina.', 'Nome, alcunha ou sinais identificam pessoa.', 'Indicar infração e fiança arbitrada quando cabível.', 'Dirigir a quem tenha qualidade para execução.'], 'Mandado não corrige prisão sem fundamento ou contra pessoa errada.', 'Ordem identifica acusado por sinais quando nome não está confirmado.', 'Sem correspondência física, não se prende homônimo por mera coincidência nominal.', ['Sinais característicos podem identificar? Sim.', 'Fiança arbitrada deve constar quando cabível? Sim.'], 'Mandado de prisão','Documento formal da ordem legítima.')
add(286,'Executor entrega exemplar do mandado ao preso com data, hora e local; recusa ou impossibilidade de recibo é documentada por duas testemunhas.', ['Regra de duplicata e entrega.', 'Registrar circunstâncias da diligência.', 'Recusa, desconhecimento ou impossibilidade de escrever exigem declaração testemunhada.'], 'Recusa de assinar não autoriza omitir registro nem inventar recibo.', 'Preso recebe exemplar e assina recibo no outro.', 'Se não pode escrever, executor registra fato com duas testemunhas.', ['Recusa dispensa documentar entrega? Não.', 'A declaração prevista tem duas testemunhas? Sim.'], 'Comprovação da entrega','Registro do conhecimento da ordem e da diligência.')
add(287,'Em infração inafiançável, falta de exibição física do mandado não impede execução de prisão judicial existente; apresentação imediata ao juiz viabiliza custódia.', ['Não confundir falta de mostrar com inexistência de ordem.', 'Atualização de 2019 prevê audiência de custódia.', 'Garantias e autenticidade da ordem permanecem.'], 'Ser crime inafiançável não cria prisão automática sem título legítimo.', 'Ordem judicial legítima é executada sem exemplar exibido na hipótese legal e preso apresentado imediatamente.', 'Suspeita de crime inafiançável não dispensa flagrante ou ordem judicial.', ['Falta de exibição equivale a ausência de ordem? Não.', 'Há apresentação para audiência de custódia? Sim.'], 'Exibição e existência da ordem','Distinção entre documento mostrado e título judicial.')
add(288,'Recolhimento prisional exige exibição e entrega dos documentos previstos e recibo com dia e hora.', ['Mandado, cópia assinada pelo executor ou guia competente nos termos do artigo.', 'Diretor ou carcereiro recebe e documenta ingresso.', 'Recibo pode constar no exemplar apresentado.'], 'Formalização do ingresso não substitui controle da legalidade da prisão.', 'Estabelecimento recebe cópia pertinente e emite recibo de ingresso.', 'Ausência de documento regular exige providências legais, não registro inventado.', ['Deve haver recibo com dia e hora? Sim.', 'Recibo pode ficar no exemplar do mandado? Sim.'], 'Registro de ingresso','Documentação do recebimento do preso.')
add(289,'Prisão fora da jurisdição nacional do juiz processante é deprecada com inteiro teor do mandado; urgência admite comunicação controlada.', ['Motivo e fiança arbitrada na requisição urgente.', 'Destinatário verifica autenticidade.', 'Remoção pelo juiz processante em até trinta dias da efetivação.'], 'Não confundir precatória com pedido de extradição internacional; prazo começa na efetivação, não no envio.', 'Réu em outra comarca é preso após confirmação da ordem.', 'Urgência permite comunicação célere, mantendo autenticidade e prazo de remoção.', ['Remoção tem máximo de trinta dias previsto? Sim.', 'Urgência dispensa verificar autenticidade? Não.'], 'Prisão deprecada','Cumprimento territorial com cooperação judicial.')
add('289-a','Mandado deve ser imediatamente registrado no banco do CNJ; execução nacional por agente policial observa comunicação e direitos.', ['Execução pode ocorrer fora do território do juiz emissor.', 'Sem registro, verificar autenticidade e comunicar emissor para registro posterior.', 'Comunicar imediatamente juiz local, que certifica e informa emissor.', 'Informar direitos; se não indicado advogado, comunicar Defensoria.', 'Dúvida sobre executor ou identidade segue controle do art. 290, §2º; CNJ regulamenta banco.'], 'Ausência de registro não autoriza prender sem ordem; nem existência de registro dispensa conferir identidade.', 'Agente em outro estado executa ordem autêntica registrada e comunica juízo local.', 'Ordem ainda não registrada exige cautelas e comunicação para registro.', ['Registro limita execução ao estado emissor? Não.', 'Sem advogado indicado deve comunicar Defensoria? Sim.'], 'Registro nacional','Controle e execução de mandados com garantias.')
add(290,'Perseguição contínua permite prisão em outra comarca, com apresentação imediata à autoridade local e providências de remoção.', ['Pode haver perda de contato visual sem interrupção da perseguição.', 'Informação fidedigna de passagem recente permite encalço na hipótese legal.', 'Dúvida fundada sobre executor ou mandado exige esclarecimento sob controle local.'], 'Não converter notícia antiga e vaga em perseguição atual nem custódia de verificação em prisão indefinida.', 'Executor segue pessoa que cruza divisa e apresenta-a imediatamente ao órgão local.', 'Dúvida concreta sobre autenticidade é esclarecida prontamente, sem ignorar garantia de liberdade.', ['Perder contato visual sempre interrompe perseguição? Não.', 'Apresentação local é imediata? Sim.'], 'Perseguição territorial','Continuidade legítima da execução fora da comarca.')
add(291,'Prisão por mandado se considera efetuada com identificação do executor, apresentação da ordem e intimação para acompanhar.', ['Definição do momento jurídico da execução.', 'Conhecimento da ordem e qualidade do executor.', 'Ler com exceção de exibição do art. 287.'], 'Não exigir chegada à cela para reconhecer toda prisão já efetuada.', 'Executor identifica-se, mostra ordem e intima réu a acompanhá-lo.', 'A hipótese específica do art. 287 exige integração, não contradição aparente.', ['Só existe prisão quando entra na cela? Não.', 'Executor deve fazer-se conhecer na regra geral? Sim.'], 'Efetivação da prisão','Momento previsto para execução da ordem.')
add(292,'Resistência própria ou de terceiros permite meios necessários e registro; algemas possuem limites constitucionais e proteção específica ao parto.', ['Auto subscrito também por duas testemunhas.', 'SV11: resistência ou receio fundado de fuga/perigo à integridade; excepcionalidade justificada por escrito.', 'Lei 13.434/2017 veda algemas nos atos médico-hospitalares preparatórios do parto, no trabalho de parto e no puerpério imediato.'], 'Nem resistência permite força ilimitada, nem proteção ao parto se reduz ao instante do nascimento.', 'Tentativa concreta de fuga exige controle necessário documentado.', 'Mulher no trabalho de parto está na vedação expressa de algemas, não em regra genérica de conveniência.', ['Uso de algemas é padrão obrigatório para todo preso? Não.', 'Vedação inclui puerpério imediato? Sim.'], 'Contenção excepcional','Necessidade documentada e proteção corporal.',[CUFF])
add(293,'Cumprir mandado de prisão em casa exige certeza do ingresso do réu e respeito à proteção domiciliar, distinguindo dia e noite.', ['À vista da ordem, intimar morador a entregar acusado.', 'Dia: duas testemunhas e ingresso forçado necessário se não atendido.', 'Noite: ordem judicial isolada não autoriza arrombamento; guardar saídas e cumprir de dia conforme regra.', 'Situação do morador é apurada como de direito, sem condenação automática.'], 'Mandado de prisão não elimina limite noturno domiciliar; exceções constitucionais têm requisitos próprios.', 'Com segurança sobre localização, ordem é cumprida de dia nos termos legais.', 'À noite sem consentimento ou exceção constitucional, não arrombar apenas pelo mandado.', ['Mandado autoriza arrombamento noturno por si só? Não.', 'Deve haver certeza sobre localização em casa? Sim.'], 'Prisão e domicílio','Cumprimento sob limites constitucionais de ingresso.',[CF])
add(294,'No flagrante, aplicar cautelas do artigo anterior naquilo que for compatível, respeitando exceção constitucional e razões concretas.', ['Flagrante não depende de mandado judicial.', 'Ingresso domiciliar exige fundamento concreto de flagrante interior.', 'Não transpor mecanicamente espera até amanhecer para toda hipótese flagrancial legítima.'], 'Rotular crime como permanente não basta sem razões concretas para entrada; achado posterior não supre fundamento ausente.', 'Razões concretas indicam flagrante no interior e ingresso é controlado pela Constituição.', 'Denúncia vaga sem confirmação não legitima automaticamente entrada à força.', ['Aplicação do artigo anterior é integral sem adaptação? Não.', 'Flagrante interior deve ter fundamento concreto? Sim.'], 'Ingresso flagrancial','Exceção constitucional demonstrada.',[CF,'https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=280'])
add(295,'Prisão especial antes de condenação definitiva separa local, não confere direitos ilimitados; diploma superior não é fundamento válido após ADPF 334.', ['STF em 2023 afastou inciso VII por violação à isonomia.', 'Demais categorias requerem enquadramento específico, sem restaurar cargos históricos extintos.', 'Sem estabelecimento específico: cela distinta; alojamento coletivo salubre é possível.', 'Transporte separado; demais direitos e deveres iguais aos do preso comum.'], 'Não gerar flashcard que conceda prisão especial apenas por diploma; decisão não significa extinção automática de todas as outras hipóteses.', 'Pessoa com diploma não obtém prisão especial só por esse título.', 'Categoria legal efetivamente aplicável exige local distinto, sem privilégios irrestritos.', ['Diploma superior basta atualmente? Não.', 'Prisão especial significa liberdade ou comodidades ilimitadas? Não.'], 'Prisão especial delimitada','Separação legal com igualdade das demais garantias.',[DIP])
add(296,'Militares abrangidos pela terminologia histórica do artigo são recolhidos em estabelecimento militar quando possível, conforme regulamentos.', ['Observar categoria e regime aplicável.', 'Não confundir local militar com imunidade à prisão.'], 'Terminologia antiga não autoriza inventar cargos atuais ou dispensar ordem legítima.', 'Praça abrangida é encaminhada ao estabelecimento militar possível e pertinente.', 'Impossibilidade concreta exige solução no regime aplicável, não soltura automática.', ['O artigo condiciona a onde for possível? Sim.', 'Local militar significa imunidade à prisão? Não.'], 'Custódia militar','Recolhimento sob regras próprias.')
add(297,'Autoridade policial pode expedir vias necessárias à diligência de cumprimento, reproduzindo fielmente mandado judicial original.', ['Derivação para execução, não nova decretação autônoma.', 'Preservar conteúdo e limites da ordem.'], 'Não ampliar pessoas, crimes ou fundamento sob pretexto de reproduzir mandado.', 'Polícia reproduz ordem para equipes executoras sem alterar conteúdo.', 'Inserir outro alvo na reprodução exige título próprio, não mera cópia alterada.', ['Polícia pode modificar fundamento da ordem ao copiar? Não.', 'Reprodução deve ser fiel? Sim.'], 'Reprodução executória','Vias necessárias sem alteração da decisão.')
add(299,'Captura baseada em mandado judicial pode ser requisitada por comunicação, com cautelas de autenticidade.', ['Meio de comunicação é flexível.', 'Ordem judicial permanece pressuposto.', 'Destinatário verifica autenticidade.'], 'Mensagem recebida não basta sem controle; não restaurar meios obrigatórios da redação antiga.', 'Autoridade confirma requisição eletrônica e existência de ordem legítima.', 'Mensagem suspeita exige verificação antes de captura indevida.', ['Pode usar meio de comunicação diverso do antigo telegrama? Sim.', 'A comunicação substitui a necessidade de mandado judicial? Não.'], 'Requisição autenticada','Comunicação da ordem sob confirmação.')
add(300,'Presos provisórios ficam separados dos definitivamente condenados; militar em flagrante segue recolhimento institucional após procedimentos legais.', ['Separação conforme LEP.', 'Lavrar procedimentos antes do encaminhamento militar.', 'Custódia permanece à disposição da autoridade competente.'], 'Recolhimento militar não elimina formalização do flagrante nem fiscalização judicial.', 'Preso cautelar é colocado separado de definitivamente condenado.', 'Militar em flagrante não segue diretamente ao quartel omitindo os procedimentos legais.', ['Provisórios devem ficar separados de condenados definitivos? Sim.', 'Militar fica livre de controle da autoridade competente? Não.'], 'Separação prisional','Regime de recolhimento conforme situação jurídica.')
add('300-a','Lei 15.280/2025 acrescentou identificação genética obrigatória para investigado preso cautelarmente e condenado por crimes contra dignidade sexual, no ingresso prisional.', ['Extração de DNA por técnica adequada e indolor.', 'Investigado precisa estar preso cautelarmente na hipótese textual.', 'Aplicação exige identificação do âmbito legal, proteção de dados e regras pertinentes.'], 'Não dizer que qualquer investigado solto por qualquer crime é abrangido por este artigo; identificação genética não prova automaticamente autoria.', 'Investigado por crime contra dignidade sexual ingressa preso cautelarmente e segue coleta legal adequada e indolor.', 'Investigação por outro delito não entra automaticamente nesta regra específica, sem prejuízo de outras normas aplicáveis.', ['Basta qualquer investigação em liberdade para aplicar este artigo? Não.', 'A técnica deve ser adequada e indolor? Sim.'], 'Identificação genética','Perfil de DNA sob hipótese legal e garantias.',[DNA])
assert len(rows)==20 and 'art-298' not in rows
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'custody reviewed')
